package com.yeyamo_mobile.api.payment_service.infrastructure.webhook;
import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;
@Entity @Table(name="payment_webhook_receipts",uniqueConstraints=@UniqueConstraint(name="uk_payment_webhook_provider_event",columnNames={"provider","provider_event_id"}))public class WebhookReceiptEntity{@Id private UUID id;@Column(nullable=false,length=40)private String provider;@Column(name="provider_event_id",nullable=false,length=160)private String providerEventId;@Column(name="payload_hash",nullable=false,length=64)private String payloadHash;@Column(name="received_at",nullable=false)private Instant receivedAt;@Column(name="processed_at")private Instant processedAt;protected WebhookReceiptEntity(){}public WebhookReceiptEntity(String provider,String event,String hash){id=UUID.randomUUID();this.provider=provider;providerEventId=event;payloadHash=hash;receivedAt=Instant.now();}public void processed(){processedAt=Instant.now();}public UUID getId(){return id;}public String getPayloadHash(){return payloadHash;}public Instant getProcessedAt(){return processedAt;}}
